 WITH CANDIDATES AS 
	( -- This CTE retrieves the candidate information
		SELECT DISTINCT
			  DVO_SRC1.CANDIDATE_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC1.CANDIDATE_BK AS CANDIDATE_BK
			, SAT_SRC1_1_1._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_1.CANDIDATE_FULL_NAME AS CANDIDATE_FULL_NAME
        FROM {{ source('eli_dv_bv', 'hub_candidate') }} DVO_SRC1
		JOIN {{ ref('sat_ssc_candidate_bvv_curr') }} SAT_SRC1_1_1 ON  DVO_SRC1.CANDIDATE_HKEY = SAT_SRC1_1_1.CANDIDATE_HKEY
	)
,MATCHES AS 
    ( -- This CTE retrieves the match information
        SELECT DISTINCT
              DVO_SRC2.MATCH_HKEY AS BASE_OBJECT_H_KEY
            , DVO_SRC2.MATCH_BK AS MATCH_BK
            , SAT_SRC1_1_2._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
            , SAT_SRC1_1_2.BILL_RATE AS BILL_RATE
            , SAT_SRC1_1_2.CONTRACTOR_TYPE AS CONTRACTOR_TYPE
            , SAT_SRC1_1_2.DATE_SUBMITTED_TO_AE AS DATE_SUBMITTED_TO_AE
            , SAT_SRC1_1_2.DATE_SUBMITTED_TO_HM AS DATE_SUBMITTED_TO_HM
            , SAT_SRC1_1_2.DIVISION AS DIVISION
            , SAT_SRC1_1_2.DOMAIN AS DOMAIN
            , SAT_SRC1_1_2.ELI_LEGACY_SYSTEM_ID AS ELI_LEGACY_SYSTEM_ID
            , SAT_SRC1_1_2.ESTIMATED_START_DATE AS ESTIMATED_START_DATE
            , SAT_SRC1_1_2.FIRST_CLIENT_INTERVIEW_DATE AS FIRST_CLIENT_INTERVIEW_DATE
            , SAT_SRC1_1_2.HOURLY_RATE_OFFERED AS HOURLY_RATE_OFFERED
            , SAT_SRC1_1_2.REJECTED AS REJECTED
            , SAT_SRC1_1_2.REJECTED_BY AS REJECTED_BY
            , SAT_SRC1_1_2.REJECTION_NOTES AS REJECTION_NOTES
            , SAT_SRC1_1_2.REJECTION_REASON AS REJECTION_REASON
            , SAT_SRC1_1_2.SEGMENT AS SEGMENT
            , SAT_SRC1_1_2.SOURCE AS SOURCE
            , SAT_SRC1_1_2.SOURCE_ADDITIONAL_INFORMATION AS SOURCE_ADDITIONAL_INFORMATION
            , SAT_SRC1_1_2.STAGE AS STAGE
            , SAT_SRC1_1_2.SUBMITTED_TO_AE AS SUBMITTED_TO_AE
            , SAT_SRC1_1_2.TR1__JOB_CONTACT__C AS CONTACT_NAME
            , SAT_SRC1_1_2.VIA_SF_LEGACY_ID AS VIA_SF_LEGACY_ID
        FROM {{ source('eli_dv_bv', 'hub_match') }} DVO_SRC2
        JOIN {{ ref('sat_bh4sf_match_bvv_curr') }} SAT_SRC1_1_2 ON DVO_SRC2.MATCH_HKEY = SAT_SRC1_1_2.MATCH_HKEY
    )
,POSITIONS AS 
    ( -- This CTE retrieves the position information
        SELECT DISTINCT
			  DVO_SRC3.POSITION_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC3.POSITION_BK AS POSITION_BK
			, SAT_SRC1_1_3._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_3.JOB_NAME AS JOB_NAME
        FROM {{ source('eli_dv_bv', 'hub_position') }} DVO_SRC3
		JOIN {{ ref('sat_bh4sf_position_bvv_curr') }} SAT_SRC1_1_3 ON  DVO_SRC3.POSITION_HKEY = SAT_SRC1_1_3.POSITION_HKEY
    )
,USERS AS 
    (
        SELECT DISTINCT
			  DVO_SRC4.USER_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC4.USER_BK AS USER_BK
			, SAT_SRC1_1_4._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_4.NAME AS ASSIGNED_RECRUITER
        FROM {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC4
		JOIN {{ ref('sat_ssc_user_bvv_curr') }} SAT_SRC1_1_4 ON  DVO_SRC4.USER_HKEY = SAT_SRC1_1_4.USER_HKEY
    )
,RECORD_TYPES AS 
    (
        SELECT DISTINCT
			  DVO_SRC8.RECORDTYPE_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC8.ID_BK AS ID_BK
			, SAT_SRC1_1_8._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_8.NAME AS RECORD_TYPE
        FROM {{ source('eli_dv_bv', 'hub_recordtype') }} DVO_SRC8
		JOIN {{ ref('sat_ssc_recordtype_bvv_curr') }} SAT_SRC1_1_8 ON  DVO_SRC8.RECORDTYPE_HKEY = SAT_SRC1_1_8.RECORDTYPE_HKEY
    )
, MATCH_LNK_CANDIDATE AS 
	( 
		SELECT DISTINCT
			  DVO_SRC5.MATCH_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC5.LNA_MATCH_CANDIDATE_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC5.CANDIDATE_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC5.MATCH_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_5._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_5._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'view_lna_match_candidate') }} DVO_SRC5
		INNER JOIN {{ ref('view_las_bh4sf_match_candidate_bvv_curr') }} SAT_SRC1_1_5 ON  DVO_SRC5.LNA_MATCH_CANDIDATE_HKEY = SAT_SRC1_1_5.LNA_MATCH_CANDIDATE_HKEY
	)
, MATCH_LNK_USER_AE AS 
	( 
		SELECT DISTINCT
			  DVO_SRC6.MATCH_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC6.LNA_MATCH_USER_ASSIGNEDRECRUITERC_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC6.USER_ASSIGNEDRECRUITERC_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC6.MATCH_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_6._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_6._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'view_lna_match_user_assignedrecruiterc') }} DVO_SRC6
		INNER JOIN {{ ref('view_las_bh4sf_match_user_assignedrecruiterc_bvv_curr') }} SAT_SRC1_1_6 ON  DVO_SRC6.LNA_MATCH_USER_ASSIGNEDRECRUITERC_HKEY = SAT_SRC1_1_6.LNA_MATCH_USER_ASSIGNEDRECRUITERC_HKEY
    )    
, MATCH_LNK_POSITION AS 
	( 
		SELECT DISTINCT
			  DVO_SRC7.MATCH_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC7.LNK_MATCH_POSITION_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC7.POSITION_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC7.MATCH_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_7.LOAD_DATE DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_7.LOAD_DATE AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'lnk_match_position') }} DVO_SRC7
		INNER JOIN {{ ref('lks_bh4sf_match_position_bvv_curr') }} SAT_SRC1_1_7 ON  DVO_SRC7.LNK_MATCH_POSITION_HKEY = SAT_SRC1_1_7.LNK_MATCH_POSITION_HKEY
    )
, MATCH_LNK_RECORD_TYPE AS 
	( 
		SELECT DISTINCT
			  DVO_SRC9.MATCH_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC9.LNA_MATCH_RECORDTYPE_HKEY AS BASE_OBJECT_L_H_KEY
			, DVO_SRC9.RECORDTYPE_HKEY AS BASE_OBJECT_F_H_KEY
            , ROW_NUMBER() OVER (
				PARTITION BY DVO_SRC9.MATCH_HKEY -- Partition by match to get the latest company
				ORDER BY SAT_SRC1_1_9._AIRBYTE_EXTRACTED_AT DESC -- Order by snapshot timestamp to get the latest
			) AS RN
			, SAT_SRC1_1_9._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
		FROM {{ source('eli_dv_bv', 'view_lna_match_recordtype') }} DVO_SRC9
		INNER JOIN {{ ref('view_las_bh4sf_match_recordtype_bvv_curr') }} SAT_SRC1_1_9 ON  DVO_SRC9.LNA_MATCH_RECORDTYPE_HKEY = SAT_SRC1_1_9.LNA_MATCH_RECORDTYPE_HKEY
	)
SELECT DISTINCT
    UPPER(SHA2(
        UPPER(REPLACE(COALESCE(TRIM(MATCHES.MATCH_BK),'~'), '\#', '\\\#')) || '\#' ||
        UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(MATCHES.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
    )) AS DIM_MATCH_HKEY
    , MATCHES.BASE_OBJECT_H_KEY AS BASE_OBJECT_H_KEY
    , MATCHES.MATCH_BK AS MATCH_BK
    , MATCHES.SNAPSHOT__TIMESTAMP AS SNAPSHOT__TIMESTAMP
    , MATCHES.BILL_RATE AS BILL_RATE
    , MATCHES.CONTRACTOR_TYPE AS CONTRACTOR_TYPE
    , MATCHES.DATE_SUBMITTED_TO_AE AS DATE_SUBMITTED_TO_AE
    , MATCHES.DATE_SUBMITTED_TO_HM AS DATE_SUBMITTED_TO_HM
    , MATCHES.DIVISION AS DIVISION
    , MATCHES.DOMAIN AS DOMAIN
    , MATCHES.ELI_LEGACY_SYSTEM_ID AS ELI_LEGACY_SYSTEM_ID
    , MATCHES.ESTIMATED_START_DATE AS ESTIMATED_START_DATE
    , MATCHES.FIRST_CLIENT_INTERVIEW_DATE AS FIRST_CLIENT_INTERVIEW_DATE
    , MATCHES.HOURLY_RATE_OFFERED AS HOURLY_RATE_OFFERED
    , MATCHES.REJECTED AS REJECTED
    , MATCHES.REJECTED_BY AS REJECTED_BY
    , MATCHES.REJECTION_NOTES AS REJECTION_NOTES
    , MATCHES.REJECTION_REASON AS REJECTION_REASON
    , MATCHES.SEGMENT AS SEGMENT
    , MATCHES.SOURCE AS SOURCE
    , MATCHES.SOURCE_ADDITIONAL_INFORMATION AS SOURCE_ADDITIONAL_INFORMATION
    , MATCHES.STAGE AS STAGE
    , MATCHES.SUBMITTED_TO_AE AS SUBMITTED_TO_AE
    , MATCHES.CONTACT_NAME AS CONTACT_NAME
    , MATCHES.VIA_SF_LEGACY_ID AS VIA_SF_LEGACY_ID
    , CANDIDATES.CANDIDATE_FULL_NAME AS APPLICANT
    , POSITIONS.JOB_NAME AS JOB_NAME
    , USERS.ASSIGNED_RECRUITER AS ASSIGNED_RECRUITER
    , RECORD_TYPES.RECORD_TYPE AS RECORD_TYPE
    FROM MATCHES MATCHES -- MAIN_HUB: HUB_MATCH
    --Join HUB_MATCH to link table on Primary key HKEY to get the candidate
    INNER JOIN MATCH_LNK_CANDIDATE MATCH_LNK_CANDIDATE ON  MATCHES.BASE_OBJECT_H_KEY = MATCH_LNK_CANDIDATE.BASE_OBJECT_H_KEY 
        AND MATCH_LNK_CANDIDATE.RN = 1 -- Get the latest candidate for the match
    --Join HUB_Candidate to link table on Foreign key HKEY
    INNER JOIN CANDIDATES CANDIDATES ON  MATCH_LNK_CANDIDATE.BASE_OBJECT_F_H_KEY = CANDIDATES.BASE_OBJECT_H_KEY
    --Join HUB_MATCH to link table on Primary key HKEY to get the user
    INNER JOIN MATCH_LNK_USER_AE MATCH_LNK_USER_AE ON  MATCHES.BASE_OBJECT_H_KEY = MATCH_LNK_USER_AE.BASE_OBJECT_H_KEY 
        AND MATCH_LNK_USER_AE.RN = 1 -- Get the latest user for the match
    --Join HUB_USER to link table on Foreign key HKEY
    INNER JOIN USERS USERS ON  MATCH_LNK_USER_AE.BASE_OBJECT_F_H_KEY = USERS.BASE_OBJECT_H_KEY
    --Join HUB_POSITION to link table on Primary key HKEY to get the job name
    INNER JOIN MATCH_LNK_POSITION MATCH_LNK_POSITION ON  MATCHES.BASE_OBJECT_H_KEY = MATCH_LNK_POSITION.BASE_OBJECT_H_KEY 
        AND MATCH_LNK_POSITION.RN = 1 -- Get the latest position for the match
    INNER JOIN POSITIONS POSITIONS ON MATCH_LNK_POSITION.BASE_OBJECT_F_H_KEY = POSITIONS.BASE_OBJECT_H_KEY
    --Join HUB_RECORDTYPE to link table on Primary key HKEY to get the record type name
    INNER JOIN MATCH_LNK_RECORD_TYPE MATCH_LNK_RECORD_TYPE ON  MATCHES.BASE_OBJECT_H_KEY = MATCH_LNK_RECORD_TYPE.BASE_OBJECT_H_KEY 
        AND MATCH_LNK_RECORD_TYPE.RN = 1 -- Get the latest record type for the match
    INNER JOIN RECORD_TYPES RECORD_TYPES ON MATCH_LNK_RECORD_TYPE.BASE_OBJECT_F_H_KEY = RECORD_TYPES.BASE_OBJECT_H_KEY
    
